CREATE OR ALTER PROCEDURE [dbo].[uspOrderLine_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @OrderId UNIQUEIDENTIFIER = NULL
	, @MenuId UNIQUEIDENTIFIER = NULL
	, @MealType NVARCHAR(MAX) = NULL
	, @ShiftId UNIQUEIDENTIFIER = NULL
	, @ContractMealId UNIQUEIDENTIFIER = NULL
	, @Quantity DECIMAL(18,6) = NULL
	, @UnitPrice DECIMAL(18,2) = NULL
	, @LineAmount DECIMAL(18,4) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[OrderId]
			, j1.[OrderNo] AS [OrderName]
			, t.[MenuId]
			, j2.[Name] AS [MenuName]
			, t.[MealType]
			, t.[ShiftId]
			, j3.[Name] AS [ShiftName]
			, t.[Quantity]
			, t.[UnitPrice]
			, t.[Note]
			, t.[ContractMealId]
			, t.[LineAmount]
			, t.[CreatedDate]
		FROM [dbo].[OrderLine] AS t
		LEFT JOIN [dbo].[Order] AS j1 ON j1.[Id] = t.[OrderId]
		LEFT JOIN [dbo].[Menu] AS j2 ON j2.[Id] = t.[MenuId]
		LEFT JOIN [dbo].[Shift] AS j3 ON j3.[Id] = t.[ShiftId]
		WHERE 1 = 1
			AND (@OrderId IS NULL OR t.[OrderId] = @OrderId)
			AND (@MenuId IS NULL OR t.[MenuId] = @MenuId)
			AND (ISNULL(@MealType, '') = '' OR t.[MealType] = @MealType)
			AND (@ShiftId IS NULL OR t.[ShiftId] = @ShiftId)
			AND (@ContractMealId IS NULL OR t.[ContractMealId] = @ContractMealId)
			AND (@Quantity IS NULL OR t.[Quantity] = @Quantity)
			AND (@UnitPrice IS NULL OR t.[UnitPrice] = @UnitPrice)
			AND (@LineAmount IS NULL OR t.[LineAmount] = @LineAmount)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderId' THEN r.[OrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderId' THEN r.[OrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderName' THEN r.[OrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderName' THEN r.[OrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'menuId' THEN r.[MenuId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'menuId' THEN r.[MenuId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'menuName' THEN r.[MenuName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'menuName' THEN r.[MenuName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'mealType' THEN r.[MealType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'mealType' THEN r.[MealType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftId' THEN r.[ShiftId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftId' THEN r.[ShiftId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftName' THEN r.[ShiftName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftName' THEN r.[ShiftName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitPrice' THEN r.[UnitPrice] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitPrice' THEN r.[UnitPrice] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contractMealId' THEN r.[ContractMealId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contractMealId' THEN r.[ContractMealId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lineAmount' THEN r.[LineAmount] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lineAmount' THEN r.[LineAmount] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
